      && verifier.VerifyVectorOfData(tablePos, 14 /*GlobalSkillHighlightResource*/, 4 /*Schale.FlatData.SkillSlotHighLightType*/, false)
      && verifier.VerifyVectorOfStrings(tablePos, 16 /*SkillGroupId*/, false)
      && verifier.VerifyVectorOfData(tablePos, 18 /*ShowSkillSlot*/, 4 /*Schale.FlatData.SkillSlotShowType*/, false)
      && verifier.VerifyVectorOfData(tablePos, 20 /*HighlightResource*/, 4 /*Schale.FlatData.SkillSlotHighLightType*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}

